def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rem = 100 - n
    if rem <= 1:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_opp_d = sum(1 for o in opp if o == 'D')
    total_opp_c = n - total_opp_d
    total_my_d = sum(1 for m in my if m == 'D')

    if total_opp_d == n:
        return 'D'

    recent_len = min(10, n)
    recent_opp = opp[-recent_len:]
    recent_opp_d = sum(1 for o in recent_opp if o == 'D')
    recent_opp_c = recent_len - recent_opp_d

    tol = 0
    pun = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                tol += 1
            else:
                pun += 1

    last_my = my[-1]
    last_opp = opp[-1]
    prev_my = my[-2] if n >= 2 else None

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_streak += 1
        else:
            break

    soft = max(2, n // 10)
    defective = total_opp_d > max(2, n // 3)
    exploit_mode = (
        pun == 0 and tol >= 1 and
        recent_opp_c >= min(6, recent_len) and
        recent_opp_d <= 2 and
        total_opp_d <= soft
    )

    if last_opp == 'D':
        if last_my == 'D':
            if defective or recent_opp_d >= 3:
                return 'D'
            if opp_streak <= 2 or total_opp_d <= 2:
                return 'C'
            return 'D'

        if prev_my == 'D':
            if opp_streak <= 1 and recent_opp_d <= 1 and total_opp_d <= soft:
                return 'C'
            if opp_streak <= 2 and recent_opp_d <= 2 and total_opp_c >= total_opp_d + 5:
                return 'C'

        return 'D'

    if last_my == 'D':
        if exploit_mode:
            return 'D'
        if defective and recent_opp_d >= 2:
            return 'D'
        return 'C'

    if exploit_mode:
        return 'D'

    if defective and recent_opp_d >= 3:
        return 'D'

    if n >= 80 and total_my_d == 0 and total_opp_d == 0 and recent_opp_d == 0 and rng.random() < 0.25:
        return 'D'

    return 'C'
